"""Generate submission reports from actual test XML/JSON and gcovr results."""
import collections, csv, datetime, json, pathlib, re, subprocess, xml.etree.ElementTree as ET
root = pathlib.Path(__file__).resolve().parents[1]
docs = root/'docs'; reports = docs/'reports'
xml = ET.parse(reports/'ctest-results.xml').getroot()
system = json.loads((reports/'system-results.json').read_text())
coverage = json.loads((reports/'coverage-summary.json').read_text())
business = json.loads((reports/'business-coverage-summary.json').read_text())
meta = json.loads((reports/'run-metadata.json').read_text())
revision = meta['tested_commit']; executed = meta['executed_at']

def write(name, text): (docs/name).write_text(text.rstrip()+'\n',encoding='utf-8')
def pct(value): return f'{value:.2f}%'
def metric(data, kind):
    total = data[kind+'_total']; covered = data[kind+'_covered']
    return f'{covered}/{total} ({100*covered/total:.2f}%)' if total else '0/0 (N/A)'
def status(case): return 'FAIL' if case.find('failure') is not None or case.find('error') is not None else 'SKIP' if case.find('skipped') is not None else 'PASS'
rows=[]
for case in xml.findall('testcase'):
    label = case.find("./properties/property[@name='cmake_labels']")
    rows.append({'category':label.get('value') if label is not None else 'integration','case':case.get('name'),'status':status(case),'seconds':case.get('time')})
counts=collections.Counter(row['category'] for row in rows)
failures=sum(row['status']!='PASS' for row in rows)
allrows=rows+[{'category':'system',**row} for row in system['tests']]
with (reports/'test-case-catalogue.csv').open('w',newline='',encoding='utf-8') as file:
    writer=csv.DictWriter(file,fieldnames=['category','case','status','seconds']); writer.writeheader(); writer.writerows(allrows)
header=f'Actual verification: {executed}. Tested source commit: `{revision}`. Platform: Ubuntu 24.04 / GCC 13 / SQLite / OpenSSL / GoogleTest under WSL. Reports were produced from execution artifacts, not estimated from source.\n\n'
summary='| Suite | Executed | Passed |\n| --- | ---: | ---: |\n'+''.join(f'| {kind} | {counts[kind]} | {sum(r["status"]=="PASS" for r in rows if r["category"]==kind)} |\n' for kind in ['unit','integration','security','perf'])
unitrows=[r for r in rows if r['category']=='unit']
write('unit-test-report.md','# Unit Test Report\n\n'+header+summary+f'\nC++ total: **{len(rows)}**, non-passing: **{failures}**. Separately, {len(system["tests"])} real-executable system scenarios ran. Pure unit suite: **{len(unitrows)}**. Memory/SQLite variants count as separate executions.\n\nThe unit suite covers dates/money, fares, seat allocation, PNR generation, input rules, refund boundaries, ticket status transitions and waitlist planning. Unit tests link the business library rather than concrete SQLite repositories. Security/integration checks are identified separately rather than counted as pure unit tests.\n\n'+ '| Test | Result | Seconds |\n| --- | --- | ---: |\n'+''.join(f'| `{r["case"]}` | {r["status"]} | {r["seconds"]} |\n' for r in unitrows)+'\nEvidence: [JUnit](reports/ctest-results.xml), [normal log](reports/normal-tests.log), [complete catalogue](reports/test-case-catalogue.csv). Sanitizer evidence: sanitizer-unit/integration/perf/security XML and logs in reports/. No Windows-native or hosted-Jenkins result is claimed.\n')
write('system-validation-report.md','# System Validation Report\n\n'+header+'The Python driver runs the compiled `rrs_app`, supplies menu inputs, opens the resulting SQLite database read-only for assertions, and restarts the app to verify persistence. Each scenario creates a fresh temporary database, avoiding dependence on earlier runs. Demo credentials are test fixtures.\n\n| Scenario | Result | Seconds |\n| --- | --- | ---: |\n'+''.join(f'| `{r["case"].split(".")[-1]}` | {r["status"]} | {r["seconds"]} |\n' for r in system['tests'])+'\nCoverage includes registration/login, quote/booking/history, foreign-PNR denial, refunds and repeated cancellation, waitlist promotion, staff booking/correction/cancellation, admin-created trains becoming bookable, admin cancellation, Ops reports/permission boundaries and restart persistence.\n\nReproduce: `python3 tools/system_validation.py build-final/rrs_app`. Evidence: [system JSON](reports/system-results.json), [system log](reports/system-validation.log), [demo smoke](reports/demo-smoke.log). This is automated system validation; subjective human usability and native Windows portability are not inferred from it.\n')
write('code-coverage-report.md','# Code Coverage Report\n\n'+header+f'**Compiled production C++ line coverage: {metric(coverage,"line")}**. Function coverage: {metric(coverage,"function")}. The denominator includes instrumented C++ in `src/` and `tools/`, including the application/menus; it excludes test sources, third-party libraries, Python automation and historical unlinked root prototypes.\n\n'+f'**Business-layer line coverage: {metric(business,"line")}**. The SRS NFR-005 target is >=80% on the business layer. Recorded status: **{"MET" if business["line_percent"]>=80 else "NOT MET"}**. Business filters include auth/booking/cancel/admin/security and common domain/date/money/result/session/clock; SQLite, UI, seed/main and file-backed audit I/O are reported in the whole-production figure instead.\n\nMeasured using GCC `--coverage -O0`, all four C++ executables and the system scenarios, then gcovr 7.0. Counts are union coverage, not averages across files or test counts.\n\nEvidence: [HTML with source details](reports/coverage.html), [raw gcovr JSON](reports/coverage.json), [summary JSON](reports/coverage-summary.json), [Cobertura XML](reports/coverage.xml), [business summary](reports/business-coverage-summary.json). The full command is in scripts/final_verify.sh. A green test suite does not imply every line is executed.\n')
write('branch-coverage-report.md','# Branch Coverage Report\n\n'+header+f'**Raw compiled production branch coverage: {metric(coverage,"branch")}**. This raw GCC figure includes compiler-generated exception/error paths.\n\n'+f'**Business decision branch coverage: {metric(business,"branch")}**. SRS NFR-005 target: >=70% business-layer branches. Recorded status: **{"MET" if business["branch_percent"]>=70 else "NOT MET"}**. This second view uses the same gcov data restricted to the documented business-layer files, with only branches explicitly marked `throw=true` by GCC/gcovr removed by `tools/extract_business_coverage.py`. This explicit exception-edge exclusion does not delete untested business decisions. The derived business-coverage.json preserves every retained branch for audit. The unfiltered result remains above and in coverage.json.\n\nBoth outcomes of validation, authorization, capacity/status decisions, refund 48h/12h boundaries, ownership, expiry/lockout and error/rollback paths are exercised. Remaining uncovered branches appear in the HTML; coverage is evidence of execution, not a proof that every requirement is correct.\n\nEvidence: [source HTML](reports/coverage.html), [raw summary](reports/coverage-summary.json), [business summary](reports/business-coverage-summary.json), [business XML](reports/business-coverage.xml).\n')
plan=[
('AUTH-01','FR-001/004, SEC-001','Register unique mobile/email; retry duplicate; verify salted hash, never plaintext','Accepted unique account, duplicate E1002, distinct salts/hashes','test_security.cpp / SEC_T01 and UT_AUTH_02'),
('AUTH-02','FR-002, SEC-004','Try wrong credentials five times; advance fixed clock 299 then 300 seconds','Lockout rejects at 299s and accepts at 300s; success resets count','test_security.cpp / SEC_T06'),
('AUTH-03','SEC-002/004','Change session role/account/token/expiry, use empty/expired/revoked copy','No privilege escalation; E1005/E1006; idle renewals validated','test_security.cpp / SEC_T04'),
('PROFILE-01','FR-003, SEC-005','Update allowed profile fields; try foreign account or changing role/credentials','Valid fields persist, ID masked, ownership denied, credentials preserved','test_security.cpp / IT_AUTH_03; AuthPersistence'),
('TRN-01','FR-005/006','Search valid/unknown/same/reverse stations and past/out-of-window dates','Only active matching service returned; invalid inputs rejected','test_final_integration.cpp / SearchRejectsUnknownSameAndOutOfWindowInputs'),
('TRN-02','FR-007/008','Display ordered stops and per-class fare','Route/time/distance and fare agree with stored configuration','test_passenger_menu.cpp'),
('BKG-01','FR-009/011','Quote 350km 3A for two travellers and compare persisted fare','Rs1750 total; stored as175000 paise','test_fare_policy.cpp; system ST_BKG_01_02'),
('BKG-02','FR-010/012','Validate 1-6 travellers, ages1-120, gender/ID/journey; decline quote','Invalid/refused data creates no reservation','test_booking_validator.cpp; test_booking_service.cpp'),
('BKG-03','FR-013/014, NFR-004','Allocate seats, generate PNR, retry same request ID and inject storage fault','Unique active seats/PNR; retry returns original; failed transaction rolls back','test_booking_service.cpp; test_reliability.cpp'),
('BKG-04','FR-015/020, SEC-002','Read own history/PNR then another passenger history/PNR','Sorted own history; foreign access E1006; invalid PNR E1001','test_security.cpp / IT_BKG_07_SEC_T08; system SEC_T08'),
('CAN-01','FR-016/017','Cancel before/at/after departure and twice','Eligible cancellation succeeds once; departed/repeat rejected without mutation','test_cancellation_service.cpp; test_cancellation_eligibility.cpp'),
('CAN-02','FR-017, BR-06','Refund boundaries48h,47h59m,12h,11h59m; waiting ticket','90/75/50 percent before departure; waiting100percent','test_refund_calculator.cpp'),
('CAN-03','FR-018/019','Fill capacity, waitlist next ticket, cancel confirmed ticket','Seat released and head promoted atomically; queue order preserved','test_seat_release.cpp; test_waitlist_plan.cpp; system IT_CAN_03'),
('ADM-01','FR-021/022','Add/rename/activate/deactivate train; validate route/schedule/class capacity','Admin only; invalid route rejected; booked load protects train/route/schedule','test_final_integration.cpp; test_schedule_coach_service.cpp'),
('STF-01','FR-023/024','Staff books for passenger, corrects name and cancels; Ops attempts same','Authorized role succeeds, owner/seat/fare invariants preserved, Ops denied','test_security.cpp; test_final_integration.cpp; system IT_STF_01_02'),
('RPT-01','FR-025','View booking/occupancy/train-wise statistics and compare SQL totals','Admin/Ops figures match persistence; passenger denied','test_report_service.cpp; system FR025'),
('SEC-05','SEC-003/005/006','Hostile/long/control input, audit injection/tamper, masking and90/91-day retention','Safe validation, sanitized events, chain verification and retention boundary','test_security.cpp / SEC_T03, T05, T07'),
('PERF-01','NFR-001/002','Generated200 trains/40 stations/20000reservations;1000 mixed operations','Latency/reliability assertions in executed suite; no duplicated seats/tickets','test_performance.cpp; test_reliability.cpp'),
('MNT-01','NFR-005/006/007','Clean build, normal/sanitizer tests, static checks and coverage','Recorded platform passes; coverage compared with80/70business thresholds','reports/ evidence; CI; platform limits recorded')]
write('test-cases.md','# Updated Test Case Document\n\n'+header+f'This updates the earlier SRS/SAD/STP cases for the integrated sprint result. There are **{len(rows)} C++ executions** and **{len(system["tests"])} system scenarios**; the exhaustive execution catalogue is [CSV](reports/test-case-catalogue.csv). IDs below group related cases and are not additional execution counts.\n\n| Group | Requirement | Preconditions / action | Expected result | Implementation evidence |\n| --- | --- | --- | --- | --- |\n'+''.join('| '+' | '.join(row)+' |\n' for row in plan)+'\nChanges since earlier sprints: real authentication replaces constructed sessions in the app; secure seed flags preserve deterministic test data; complete cancellation replaces the interim release-only adapter; admin sources use shared interfaces; final regression cases cover inactive availability, same-station fare, route protection, staff cancellation and search validation; system checks cover all four roles and process restart.\n\nExecuted outcomes are stored per case in the CSV/XML/JSON; they should be regenerated after any code change. Historical reports retain their original context and are superseded by this final run for release totals.\n')
write('defect-report.md','# Integration Defect and Regression Report\n\n'+header+'''| Defect | Before | Correction | Evidence |
| --- | --- | --- | --- |
| Missing/incompatible train admin interface | Integrated build failed on missing admin/train_admin_service.h and incompatible repository/result calls | Added shared-interface header/service and replaced placeholder main with real auth/role menus | build-before.log; final build.log |
| Inactive train still exposed availability | Configuration/schedule lookup succeeded after deactivation | Verify active train before availability; reject invalid same-station quotes | regression-before/after.log |
| Staff cancellation incorrectly forbidden | Cancellation allowed only Passenger despite role matrix | Permit authenticated Staff/Admin; preserve passenger ownership and deny Ops | regression-before/after.log; system staff/admin cases |
| Seed/auth merge conflict | Different seed signatures and disabled credentials conflicted with runnable demo | Preserve idempotent sample seeding, optional hash-backed demo logins and existing accounts | seed unit/integration cases; executable auth cases |
| Administrator route editing accepted no signed sentinel | Numeric input parser could not read -1 origin/terminus times | Bounded signed integer input when field range permits negative values | system ST_ADM_01 |
| Shared performance/reliability DB paths | Concurrent test runs interfered with temporary files | Unique per-process random filenames | final performance/reliability pass logs |

The before/fix comparison uses archived pre-fix service fixtures with the current new regression tests in an isolated source copy. Four failing executions represent two parameterized scenario names on memory and SQLite; they are intentionally failing evidence, not failures in the current release. Reproduce with `python3 tools/reproduce_regressions.py`. The current regressions pass and are part of the full suite.

Known limits: the verified deployment is one local process with SQLite and file audit, WSL/GCC is the recorded platform, a separately hosted Jenkins/SonarQube service and native Windows build were not exercised, and there is no real railway/payment integration. Audit truncation needs an external anchor; Windows ACLs remain relevant on mounted drives.
''')
print(f'Generated reports for {len(rows)} C++ tests and {len(system["tests"])} system scenarios')
